params = 70e9
stages = {"none": 16, "zero1": 8, "zero2": 4, "zero3": 2}
for name, bytes_per_param in stages.items():
    total = params * bytes_per_param / 1e9
    print(f"{name:6s}: {total:,.0f} GB total -> {total/8:,.0f} GB per GPU (8x)")

import math
peak, total, warmup = 3e-4, 10000, 500
def lr(step):
    if step < warmup: return peak * step / warmup
    p = (step - warmup) / (total - warmup)
    return peak * 0.1 + 0.5 * (peak - peak*0.1) * (1 + math.cos(math.pi*p))
for s in [0, 500, 5000, 9999]:
    print(f"step {s:5d}: lr={lr(s):.2e}")

def reward(pred, gold):
    try:
        return 1.0 if abs(float(pred) - float(gold)) < 1e-6 else 0.0
    except ValueError:
        return 0.0
print("reward:", reward("42", "42"), reward("41", "42"))
